(function(){
 'use strict';
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>'PKR '+new Intl.NumberFormat('en-PK',{maximumFractionDigits:2}).format(Number(n||0));
 const label=s=>String(s||'').replaceAll('_',' ');
 function create({db,getSession,go,toast,submit,refreshIdentity}){
  let identity=null,owner=null,orders=[],accounts=[],adminData=null;
  const rpc=async(name,args)=>{const {data,error}=await db.rpc(name,args);if(error)throw error;return data};
  const page=document.createElement('section');page.className='page';page.id='page-shopping';
  page.innerHTML='<div class="heading"><div><div class="eyebrow">Your shopping account</div><h1>My orders & payments</h1><p>Track your orders, submit advance payments and check approval progress.</p></div><button class="btn" data-page="shop">Continue shopping</button></div><div id="shoppingProfile"></div><div class="shopping-rule"><strong>Before dispatch</strong><p>Orders up to PKR 6,000 require PKR 600 advance; above PKR 6,000, the advance is 10% of the final order total including delivery. If the entire order is below PKR 600, only the order total is payable. Your approved advance is deducted from the amount collected on delivery.</p></div><div id="shoppingOrderList" aria-live="polite"></div><details class="shopping-membership"><summary>Become a network member</summary><p>Membership is a separate choice. Your shopping orders and payment history will stay with this account.</p><form id="shoppingMembership" class="form"><label>Member referral code<input name="referral" required autocomplete="off"></label><label class="shopping-consent"><input type="checkbox" name="consent" required> I agree to join the member network and accept the membership terms.</label><button class="btn primary" type="submit">Join member network</button></form></details>';
  document.querySelector('#page-shop').parentElement.append(page);
  async function identify(session){
   owner=session?.user.id||null;identity=null;document.body.classList.remove('shopping-user-active');
   if(!owner)return null;const current=owner;const data=await rpc('my_shopping_account');if(owner!==current)return null;identity=data;document.body.classList.toggle('shopping-user-active',!!data.customer_only);return data;
  }
  function clear(){identity=null;owner=null;orders=[];accounts=[];document.body.classList.remove('shopping-user-active');document.getElementById('shoppingOrderList').replaceChildren();document.getElementById('shoppingProfile').replaceChildren()}
  async function signup({name,phone,email,password,affiliate,consent,country='PK'}){
   const {data,error}=await db.auth.signUp({email:email.trim(),password,options:{emailRedirectTo:location.origin+location.pathname+'#shopping',data:{registration_type:'customer',full_name:name.trim(),phone:phone.trim(),country_code:country,affiliate_code:affiliate||null,terms_accepted:consent?'true':'false',terms_version:'shopping-v1'}}});if(error)throw error;return data;
  }
  function checkoutUI({form,session,affiliate,total}){
   let box=document.getElementById('shoppingCheckout');
   if(!box){box=document.createElement('fieldset');box.id='shoppingCheckout';box.className='shopping-checkout';box.innerHTML='<legend>Your order & payment</legend><div id="shoppingCheckoutAuth"><p>Create your free shopping User account to place and track this order.</p><div class="row"><label>Email<input id="shoppingEmail" type="email" autocomplete="email"></label><label>Create password<input id="shoppingPassword" type="password" autocomplete="new-password" minlength="10"></label></div><label class="shopping-consent"><input id="shoppingConsent" type="checkbox"> I agree to create a shopping account and accept the account and order terms.</label><button class="btn small" type="button" data-shopping-login>Already have an account? Sign in</button></div><div class="checkout-choice-grid"><label><input type="radio" name="shoppingFunding" value="ADVANCE" checked><span><b>Pay advance</b><small>Pay to the company account, then submit your transaction ID from My orders & payments.</small></span></label><label id="shoppingSponsorChoice"><input type="radio" name="shoppingFunding" value="SPONSOR"><span><b>Request sponsor hold</b><small>Your linked sponsor approves a refundable security hold. The full order amount remains payable on delivery.</small></span></label></div><p id="shoppingAmountPreview" class="shopping-rule"></p><p id="shoppingCheckoutNotice" role="status"></p>';form.insertBefore(box,form.querySelector('button[type="submit"]'))}
   const show=!session||identity?.customer_only||!!affiliate;box.hidden=!show;box.disabled=!show;
   document.getElementById('shoppingCheckoutAuth').hidden=!!session;
   for(const id of ['shoppingEmail','shoppingPassword','shoppingConsent']){const input=document.getElementById(id);input.required=show&&!session;input.disabled=!!session||!show}
   const hasSponsor=!!affiliate||!!identity?.has_sponsor;document.getElementById('shoppingSponsorChoice').hidden=!hasSponsor;
   if(!hasSponsor)box.querySelector('[value="ADVANCE"]').checked=true;
   const advance=Math.min(total,total<=6000?600:Math.round(total*10)/100);
   const sponsor=box.querySelector('[name="shoppingFunding"]:checked').value==='SPONSOR';
   document.getElementById('shoppingAmountPreview').textContent=sponsor?`Sponsor security: ${total<=6000?'2 MIO':money(advance)+' converted to MIO at the order rate'}. You will pay ${money(total)} on delivery after sponsor approval.`:`Advance required: ${money(advance)}. Remaining on delivery after approval: ${money(Math.max(0,total-advance))}. Dispatch starts only after payment approval.`;
   if(show){form.querySelector('button[type="submit"]').textContent=session?'Place order': 'Create User account & continue';document.getElementById('checkoutRewardNote').textContent='Your order will be saved in your shopping User dashboard.';document.getElementById('checkoutFulfilmentNote').textContent='After placing your order, complete the approval step in My orders & payments.'}
  }
  function paymentOptions(){return accounts.map(a=>`<option value="${a.id}">${escape(a.bank_name)} · ${escape(a.account_number)}</option>`).join('')}
  function bankCard(a){return `<div class="shopping-bank"><strong>${escape(a.bank_name)}</strong><span>${escape(a.account_title)}</span><b>${escape(a.account_number)}</b><small>${escape(a.instructions)}</small></div>`}
  function orderCard(o){const f=o.funding,closed=['cancelled','returned'].includes(o.status),status=f.method==='SPONSOR'?o.sponsor_status:f.status,advance=Number(f.paid_pkr||0),canPay=f.method==='ADVANCE'&&['awaiting_payment','rejected'].includes(f.status)&&!closed;
   return `<article class="shopping-order"><header><div><small>${new Date(o.created_at).toLocaleString()}</small><h2>${escape(o.order_code)}</h2></div><span class="pill">${escape(label(o.status))}</span></header><div class="shopping-totals"><div><span>Order total</span><strong>${money(o.total_pkr)}</strong></div><div><span>${f.method==='SPONSOR'?'Refundable sponsor hold':'Advance required'}</span><strong>${f.method==='SPONSOR'?Number(f.hold_mio).toFixed(4)+' MIO':money(f.required_pkr)}</strong></div><div><span>Remaining on delivery</span><strong>${closed?'—':money(o.cod_due_pkr)}</strong></div></div><p class="shopping-status"><strong>${escape(label(status))}</strong> · ${f.method==='SPONSOR'?'Sponsor security is refundable and is not a payment against your order.':advance>0?'Advance received: '+money(advance)+'.':f.status==='submitted'?'Your payment is awaiting verification.':'Pay the required advance to approve this order.'}</p>${f.review_note?`<p>${escape(f.review_note)}</p>`:''}${f.transaction_id?`<small>Transaction ID: ${escape(f.transaction_id)}</small>`:''}<details><summary>Order details</summary><ul>${o.items.map(i=>`<li>${escape(i.name)} × ${i.quantity} · ${money(i.unit_price)}</li>`).join('')}</ul><p>${escape(o.shipping_name)} · ${escape(o.shipping_address)}, ${escape(o.shipping_city)}</p></details>${canPay?`<section class="shopping-pay"><h3>Pay ${money(f.required_pkr)} advance</h3>${accounts.length?`<div class="shopping-bank-list">${accounts.map(bankCard).join('')}</div><form class="form shopping-payment-form" data-id="${o.id}"><label>Account you paid to<select name="account" required><option value="">Select payment account</option>${paymentOptions()}</select></label><label>Transaction ID<input name="transaction" required minlength="4" maxlength="120" autocomplete="off"></label><p>Transfer exactly ${money(f.required_pkr)} before submitting. Approval follows verification of the payment.</p><button class="btn primary" type="submit">Submit payment for approval</button></form>`:'<p role="status">Payment account details are being configured. Please contact support before paying. Your order is saved and will not be dispatched yet.</p>'}</section>`:''}${o.status==='placed'&&['awaiting_payment','pending','rejected'].includes(f.status)?`<button class="btn small" type="button" data-shopping-cancel="${o.id}">Cancel unpaid order</button>`:''}</article>`;
  }
  async function refresh(){const uid=getSession()?.user.id;if(!uid)return;document.getElementById('shoppingOrderList').innerHTML='<p role="status">Loading your orders…</p>';try{const [rows,banks]=await Promise.all([rpc('my_shopping_orders'),rpc('shopping_payment_accounts')]);if(getSession()?.user.id!==uid)return;orders=rows;accounts=banks;document.getElementById('shoppingOrderList').innerHTML=rows.length?rows.map(orderCard).join(''):'<div class="empty"><h2>Your orders will appear here</h2><p>Shop the marketplace, then return here to manage your payments.</p><button class="btn primary" data-page="shop">Browse products</button></div>';page.querySelector('.shopping-membership').hidden=!identity?.customer_only;document.getElementById('shoppingProfile').innerHTML=identity?.customer_only&&!identity.terms_accepted?`<form class="form shopping-profile-form"><h2>Complete your shopping profile</h2><label>Full name<input name="full_name" value="${escape(identity.full_name)}" required minlength="2"></label><label>Phone<input name="phone" type="tel" value="${escape(identity.phone)}" required minlength="7"></label><label class="shopping-consent"><input name="consent" type="checkbox" required> I agree to the shopping account and order terms.</label><button class="btn primary" type="submit">Save profile</button></form>`:'';}catch(e){document.getElementById('shoppingOrderList').innerHTML='<p role="alert">Your orders could not be loaded. <button class="btn" data-shopping-refresh>Try again</button></p>';throw e}}
  async function admin(){
   let target=document.getElementById('adminShoppingPayments');if(!target){target=document.createElement('section');target.id='adminShoppingPayments';target.className='card shopping-admin';document.getElementById('adminOrders').closest('.card').before(target)}
   const uid=getSession()?.user.id;const data=await rpc('admin_shopping_payments');if(getSession()?.user.id!==uid)return;adminData=data;
   target.innerHTML=`<div class="card-body"><h2>Customer advances & payment accounts</h2><p>Verify transfers against company bank records. An approved advance reduces COD; it does not mark the full order as paid.</p><details><summary>Manage payment accounts (${data.accounts.length})</summary><div class="shopping-bank-list">${data.accounts.map(a=>`<div>${bankCard(a)}<small>${a.active?'Active':'Inactive'}</small> <button class="btn small" data-shopping-edit-account="${a.id}">Edit</button></div>`).join('')}</div><form class="form" id="shoppingBankForm"><input name="id" type="hidden"><div class="row"><label>Bank / wallet name<input name="bank" required maxlength="120"></label><label>Account title<input name="title" required maxlength="160"></label></div><label>Account number / IBAN<input name="number" required maxlength="120"></label><label>Payment instructions<textarea name="instructions" maxlength="1000"></textarea></label><label class="shopping-consent"><input type="checkbox" name="active" checked> Available for customer payments</label><button class="btn primary" type="submit">Save payment account</button><button class="btn" type="reset">New account</button></form></details><div class="shopping-admin-payments">${data.payments.length?data.payments.map(f=>`<article class="shopping-order"><h3>${escape(f.order_code)} · ${escape(f.customer_name)}</h3><p>${escape(label(f.status))} · Advance ${money(f.required_pkr)} · COD ${money(f.cod_due_pkr)}</p>${f.transaction_id?`<p>Transaction ID: <strong>${escape(f.transaction_id)}</strong></p>${f.account_snapshot?bankCard(f.account_snapshot):''}`:''}${f.status==='submitted'?`<form class="form shopping-review-form" data-id="${f.order_id}"><label>Decision<select name="approve"><option value="true">Approve verified payment</option><option value="false">Reject payment claim</option></select></label><label>Amount verified (PKR)<input name="amount" type="number" min="0" step="0.01"></label><label>Verification / rejection note<textarea name="note" required minlength="10"></textarea></label><button class="btn primary" type="submit">Save decision</button></form>`:f.status==='refund_due'?`<form class="form shopping-refund-form" data-id="${f.order_id}"><label>Completed refund transaction reference<input name="reference" required minlength="8"></label><button class="btn" type="submit">Record completed refund</button></form>`:''}</article>`).join(''):'<p>No customer advances yet.</p>'}</div></div>`;
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-shopping-refresh],[data-shopping-cancel],[data-shopping-edit-account],[data-shopping-login]');if(!b)return;if(b.hasAttribute('data-shopping-login')){document.getElementById('cartModal').classList.remove('open');sessionStorage.setItem('mio-resume-shopping','1');go('login');return}if(b.hasAttribute('data-shopping-edit-account')){const a=adminData.accounts.find(a=>a.id===b.dataset.shoppingEditAccount),f=document.getElementById('shoppingBankForm');for(const [key,value]of Object.entries({id:a.id,bank:a.bank_name,title:a.account_title,number:a.account_number,instructions:a.instructions}))f.elements[key].value=value;f.elements.active.checked=a.active;f.scrollIntoView({block:'center',behavior:'smooth'});return}submit({querySelector:()=>b},async()=>{if(b.dataset.shoppingCancel)await rpc('cancel_unpaid_order',{p_order_id:b.dataset.shoppingCancel});await refresh()})});
  document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('.shopping-payment-form,.shopping-review-form,.shopping-refund-form,.shopping-profile-form,#shoppingBankForm,#shoppingMembership'))return;e.preventDefault();submit(f,async()=>{const v=f.elements;if(f.matches('.shopping-payment-form'))await rpc('submit_shopping_advance',{p_order_id:f.dataset.id,p_account_id:v.account.value,p_transaction_id:v.transaction.value.trim()});else if(f.matches('.shopping-review-form'))await rpc('admin_review_shopping_advance',{p_order_id:f.dataset.id,p_approve:v.approve.value==='true',p_verified_pkr:v.amount.value?Number(v.amount.value):null,p_note:v.note.value.trim()});else if(f.matches('.shopping-refund-form'))await rpc('admin_record_shopping_refund',{p_order_id:f.dataset.id,p_reference:v.reference.value.trim()});else if(f.id==='shoppingBankForm')await rpc('admin_save_shopping_payment_account',{p_id:v.id.value||null,p_bank:v.bank.value,p_title:v.title.value,p_number:v.number.value,p_instructions:v.instructions.value,p_active:v.active.checked});else if(f.id==='shoppingMembership'){await rpc('join_network_from_shopping',{p_referral_code:v.referral.value,p_consent:v.consent.checked});await refreshIdentity();go('dashboard');toast('Membership created. Your shopping history is preserved.');return}else{await rpc('complete_shopping_profile',{p_name:v.full_name.value,p_phone:v.phone.value,p_consent:v.consent.checked});await identify(getSession())}toast('Saved successfully');if(f.closest('#adminShoppingPayments'))await admin();else await refresh()})});
  return {identify,clear,signup,checkoutUI,refresh,admin,get isCustomer(){return !!identity?.customer_only},get hasCustomer(){return !!identity?.has_customer},get sponsorCode(){return identity?.sponsor_code||''}};
 }
 window.MioShopping={create};
})();
